    function updateDOM(fromNode, toNode) {
        if (!fromNode || !toNode) return;
        const fromAttrs = fromNode.attributes, toAttrs = toNode.attributes;
        for (const attr of toAttrs) { if (fromNode.getAttribute(attr.name) !== attr.value) fromNode.setAttribute(attr.name, attr.value); }
        for (const attr of fromAttrs) { if (!toNode.hasAttribute(attr.name)) fromNode.removeAttribute(attr.name); }
        const fromChildren = Array.from(fromNode.childNodes), toChildren = Array.from(toNode.childNodes);
        for (let i = 0; i < Math.max(fromChildren.length, toChildren.length); i++) {
            const fromChild = fromChildren[i], toChild = toChildren[i];
            if (!toChild) fromNode.removeChild(fromChild);
            else if (!fromChild) fromNode.appendChild(toChild.cloneNode(true));
            else if (fromChild.nodeType !== toChild.nodeType || fromChild.tagName !== toChild.tagName) fromNode.replaceChild(toChild.cloneNode(true), fromChild);
            else if (fromChild.nodeType === Node.TEXT_NODE) { if (fromChild.textContent !== toChild.textContent) fromChild.textContent = toChild.textContent; }
            else if (fromChild.nodeType === Node.ELEMENT_NODE) updateDOM(fromChild, toChild);
        }
    }

