    function renderApp() {
        const root = document.getElementById('app-root');
        if (!root) return;
        try {
            const newHTML = generateHTML(globalData);
            const tempDiv = document.createElement('div');
            tempDiv.innerHTML = newHTML;
            const newContent = tempDiv.firstElementChild;
            if (root.firstElementChild) {
                updateDOM(root.firstElementChild, newContent);
            } else {
                root.appendChild(newContent);
            }
            // 绑定日历点击事件
            document.querySelectorAll('.cal-day').forEach(dayEl => {
                dayEl.addEventListener('click', function(e) {
                    const day = parseInt(this.dataset.day);
                    const event = (globalData['活动日历'] || []).find(e => e.日期 === day);
                    if (event) {
                        const popup = document.getElementById('calPopup');
                        popup.innerHTML = `<div class="pop-title">${event.名称}</div>
                            <div class="pop-body">📍 ${event.地点}<br>🕒 ${event.持续时间}<br>${event.描述}</div>`;
                        popup.style.display = 'block';
                        popup.style.left = (e.clientX + 15) + 'px';
                        popup.style.top = (e.clientY + 15) + 'px';
                        setTimeout(() => { popup.style.display = 'none'; }, 3000);
                    }
                });
            });
            // 雨滴Canvas
            initRainEffect();

            // 花瓣初始化
            const petalContainer = document.getElementById('haikuPetalContainer');
            if (petalContainer) {
                petalContainer.innerHTML = '';
                for (let i = 0; i < 10; i++) {
                    const petal = document.createElement('div');
                    petal.className = 'petal';
                    petal.style.left = Math.random() * 100 + '%';
                    petal.style.animationDuration = (Math.random() * 4 + 4) + 's';
                    petal.style.animationDelay = (Math.random() * 3) + 's';
                    petalContainer.appendChild(petal);
                }
            }
        } catch (err) {
            console.error(err);
        }
    }

    // 雨滴特效
    function initRainEffect() {
        const canvas = document.getElementById('rain-canvas');
        if (!canvas) return;
        const weather = getValue(globalData, '进程.当日天气', '晴天');
        const rainWeathers = ['阵雨', '雷阵雨', '暴雨'];
        if (!rainWeathers.includes(weather)) {
            canvas.style.display = 'none';
            return;
        }
        canvas.style.display = 'block';
        canvas.width = canvas.parentElement.clientWidth;
        canvas.height = canvas.parentElement.clientHeight;
        const ctx = canvas.getContext('2d');
        let drops = [];
        const intensity = weather === '暴雨' ? 200 : weather === '雷阵雨' ? 150 : 100;
        for (let i = 0; i < intensity; i++) {
            drops.push({
                x: Math.random() * canvas.width,
                y: Math.random() * canvas.height,
                len: Math.random() * 15 + 8,
                speed: Math.random() * 8 + 14
            });
        }
        function draw() {
            if (canvas.style.display === 'none') return;
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.strokeStyle = 'rgba(200,220,255,0.5)';
            ctx.lineWidth = 1;
            for (let d of drops) {
                d.y += d.speed;
                if (d.y > canvas.height) { d.y = -10; d.x = Math.random() * canvas.width; }
                ctx.beginPath();
                ctx.moveTo(d.x, d.y);
                ctx.lineTo(d.x - 0.5, d.y - d.len);
                ctx.stroke();
            }
            requestAnimationFrame(draw);
        }
        draw();
    }

    const init = async () => {

        await loadHaikuPool();

        const Mvu = getMvuInstance();
        if (Mvu && Mvu.events) {
            document.addEventListener(Mvu.events.VARIABLE_UPDATE_ENDED, (e) => {
                if (e.detail && e.detail.stat_data) {
                    globalData = e.detail.stat_data;
                    renderApp();
                }
            });
            const wrapper = Mvu.getMvuData({ type: 'message', message_id: -1 });
            if (wrapper) {
                globalData = wrapper.stat_data || wrapper;
                renderApp();
            }
        } else {
            renderApp();
            setTimeout(init, 1000);
        }
    };

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
</script>
</body>
</html>
